import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    Validator
from taf.fdsw.rc.schemas.FDSW22A.autoconnection_parameters_builder_22a import \
    AutoconnectionParametersBuilder22A

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder23B(AutoconnectionParametersBuilder22A):
    def __init__(self, **kwargs):
        super(AutoconnectionParametersBuilder23B, self).__init__(**kwargs)

        if 'enforce_cmp_init' in kwargs:
            enforce_cmp_init = kwargs['enforce_cmp_init']

            self.certifcate_parameters.update(enforceCmpInit=Validator.validate_param(
                'enforce_cmp_init',
                enforce_cmp_init,
                (enforce_cmp_init in ['YES', 'NO'])))

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder23B, self).as_dict()
        return attributes
